<?php require_once __DIR__.'/../cms/config.php'; if(logged_in()){header('Location: dashboard.php');exit;} if(!is_file(CMS_DATA.'/auth.json')){header('Location: ../cms/setup.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $a=read_json(CMS_DATA.'/auth.json',[]); if(password_verify($_POST['password']??'',$a['password_hash']??'')){$_SESSION['cms_auth']=1;header('Location: dashboard.php');exit;} $error='Invalid admin password.'; } ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YonoLootZone Admin Login</title><link rel="stylesheet" href="dist/css/adminlte.min.css"><link rel="stylesheet" href="plugins/fontawesome-free/css/all.min.css"><style>body{background:linear-gradient(135deg,#101827,#251329)}.login-box{width:420px}.card{border-radius:18px}.btn-pink{background:#e00068;border-color:#e00068;color:#fff}</style></head><body class="hold-transition login-page"><div class="login-box"><div class="text-center text-white mb-4"><h2><b>Yono</b><span style="color:#ff5aa2">LootZone</span></h2><p>Administrator Control Panel</p></div><div class="card card-outline card-danger"><div class="card-header text-center"><b>Sign In</b></div><div class="card-body"><?php if($error):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><form method="post"><div class="input-group mb-3"><input type="password" name="password" class="form-control" placeholder="Admin password" required><div class="input-group-append"><div class="input-group-text"><i class="fas fa-lock"></i></div></div></div><button class="btn btn-pink btn-block font-weight-bold">Login</button></form></div></div></div></body></html>